settings.css:
body{background-color:rgba(0,0,0,0);margin:0;overflow:hidden} /* Chat des lives linedev (page dock.html de Social Stream Ninja, CSS posé dans la source OBS par obs/generer.mjs).
   Même règles que chat-latshow.css. Habillage « papa », le bureau du matin (2026-11-08) : Bricolage Grotesque, texte
   encre et pseudo vermillon foncé (lisible en 14 px) sur le panneau clair que dessine la page de la scène. */
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@14,400;14,700&display=swap');
#menu,#context-menu{display:none!important}
html,body,#output{background:transparent!important}
#output{left:0!important;right:0!important;width:auto!important;box-sizing:border-box!important;padding:0 14px 12px!important}
.highlight-chat{background:transparent!important;border:0!important;box-shadow:none!important;padding:3px 0!important;margin:0!important}
.hl-message{display:block!important;font:400 14px/1.4 'Bricolage Grotesque',sans-serif!important;color:#1E1B16!important;text-shadow:none!important;-webkit-text-stroke:0!important;letter-spacing:0!important;text-indent:0!important;padding:0!important;margin:0!important;overflow:visible!important}
.hl-source-type{width:12px!important;height:12px!important;vertical-align:-2px!important;margin:0 6px 0 0!important;opacity:.85}
.hl-name{display:inline!important;font:700 14px/1.4 'Bricolage Grotesque',sans-serif!important;color:#B4360F!important;margin-right:6px!important;text-shadow:none!important;-webkit-text-stroke:0!important}
.hl-content{display:inline!important;font:400 14px/1.4 'Bricolage Grotesque',sans-serif!important;color:#1E1B16!important;text-shadow:none!important;-webkit-text-stroke:0!important}

